self.addEventListener("install",t=>t.waitUntil(onInstall(t))),self.addEventListener("activate",t=>t.waitUntil(onActivate(t))),self.addEventListener("fetch",t=>{const e=new URL(t.request.url);e.protocol==="ipc:"||e.protocol==="tauri:"||e.hostname==="ipc.localhost"||e.hostname==="tauri.localhost"||e.hostname==="127.0.0.1"||e.hostname==="localhost"||t.request.url.startsWith("http")&&allowCache(t.request)&&urlNeedsCaching(t.request.url)&&t.respondWith(onFetch(t))});const cachePostfix=location.host.startsWith("localhost")?`${Date.now()}`:new Date().toISOString().split("T")[0].replace(/-/g,""),cacheNamePrefix="offline-cache-",cacheName=`${cacheNamePrefix}${cachePostfix}`;async function onInstall(t){self.skipWaiting()}async function onActivate(t){const e=await caches.keys();await Promise.all(e.filter(a=>a.startsWith(cacheNamePrefix)&&a!==cacheName).map(a=>caches.delete(a))),await self.clients.claim()}async function onFetch(t){let e=applyCacheBusting(t.request);const a=await caches.open(cacheName),n=await a.match(e),r=fetch(e).then(c=>(c&&c.ok&&a.put(e,c.clone()),c)).catch(c=>{console.error("Background fetch failed:",c)});return n?(t.waitUntil(r),n):r}function urlNeedsCaching(t){return!(t.startsWith("https://cdn.myfi.ws")||t.startsWith("http://127.0.0.1:1426"))}function applyCacheBusting(t){try{const e=new URL(t.url);return e.searchParams.set("_",cacheName),new Request(e.toString(),t)}catch{return t}}function allowCache(t){return!(t.method!=="GET"||t.mode==="navigate")}
